import{_ as i,C as o,o as l,c,j as t,a as d,E as s,a2 as n}from"./chunks/framework.sc8Z_ZE3.js";const v=JSON.parse('{"title":"Policies and four-eyes","description":"","frontmatter":{},"headers":[],"relativePath":"rules/policies.md","filePath":"rules/policies.md"}'),h={name:"rules/policies.md"};function p(g,e,u,m,f,y){const r=o("Badge"),a=o("Shot");return l(),c("div",null,[e[0]||(e[0]=t("h1",{id:"policies-and-four-eyes",tabindex:"-1"},[d("Policies and four-eyes "),t("a",{class:"header-anchor",href:"#policies-and-four-eyes","aria-label":'Permalink to "Policies and four-eyes"'},"​")],-1)),s(r,{type:"built",text:"Built"}),e[1]||(e[1]=n('<p>Cedar policies decide what people and agents may do. By default, every policy change gets a second pair of eyes before it goes live.</p><p>Octryx AI stores its rules as Cedar policies. A guided builder and templates write the Cedar for you, so you don&#39;t have to. Open <strong>Admin › Rules › Policies</strong>.</p><h2 id="what-a-policy-can-decide" tabindex="-1">What a policy can decide <a class="header-anchor" href="#what-a-policy-can-decide" aria-label="Permalink to &quot;What a policy can decide&quot;">​</a></h2><p>Each policy answers a question of the form &quot;May <em>principal</em> do <em>action</em> on <em>resource</em> in <em>Workspace</em>?&quot;. The actions are grouped in the builder:</p><ul><li><strong>Connectors &amp; tools</strong>: <strong>Use a non-connector tool</strong>, <strong>Read through a connector</strong>, <strong>Change data through a connector</strong></li><li><strong>Models</strong>: <strong>Call a model</strong> (on the seat route or the governed route)</li><li><strong>Tool results</strong>: <strong>Receive a tool result</strong> before a model sees it</li><li><strong>Coding agent</strong>: <strong>Run a shell command</strong>, <strong>Read a file</strong>, <strong>Write or edit a file</strong></li><li><strong>Knowledge</strong>: <strong>Use remote embeddings</strong>, <strong>Use a remote reranker</strong></li><li><strong>Seats</strong>: <strong>Use a personal seat</strong></li><li><strong>Devices</strong>: <strong>Run a chat request on an own device</strong></li></ul><p>The platform generates a baseline from your other settings, such as <strong>Classification</strong> and each Workspace&#39;s model policy. Your own policies add <strong>forbid</strong> rules on top of it. When no policy permits a request, Cedar&#39;s default is deny.</p><h2 id="the-policies-page" tabindex="-1">The Policies page <a class="header-anchor" href="#the-policies-page" aria-label="Permalink to &quot;The Policies page&quot;">​</a></h2>',7)),s(a,{src:"/shots/policies.png",alt:"Admin › Rules › Policies in shadow mode, with templates to start from",caption:"The Policies tab, in shadow mode, with templates to start from."}),e[2]||(e[2]=n(`<p>The page has four tabs: <strong>Policies</strong>, <strong>Templates</strong>, <strong>Detectors</strong> and <strong>Test bench</strong>. Next to the tabs, the policy engine card shows the current mode. Click it to open <strong>Status &amp; mode</strong>, where you choose <strong>Off</strong>, <strong>Shadow</strong> or <strong>Enforce</strong>. A badge beside it shows the current approval rule.</p><p>The policy list shows generated and custom policies with their status (<strong>Generated</strong>, <strong>Published</strong>, or a draft state such as <strong>Draft · new</strong> or <strong>In review · changed</strong>) and their effect (<strong>Allows</strong>, <strong>Blocks</strong>, <strong>Masks</strong>, <strong>Routes</strong> or <strong>Masks · routes</strong>). From each policy&#39;s menu you can <strong>Edit</strong> (<strong>Edit Cedar</strong> for hand-written policies), <strong>Duplicate</strong>, <strong>Test</strong>, <strong>Show in Decisions</strong> or <strong>Remove</strong> it.</p><h3 id="the-policy-builder" tabindex="-1">The policy builder <a class="header-anchor" href="#the-policy-builder" aria-label="Permalink to &quot;The policy builder&quot;">​</a></h3><p><strong>+ New policy</strong> opens the builder. It walks you through these steps:</p><ol><li><strong>Basics</strong>: name and description. The <code>@id</code> follows the name.</li><li><strong>Who</strong>: everyone, or members of roles, groups or named users.</li><li><strong>What</strong>: the actions to block, and optionally which connector, tool, model, command or path.</li><li><strong>Content</strong>: what the content scan must find. Shown only for model calls and tool results.</li><li><strong>Where</strong>: all Workspaces, chosen ones, a classification, or named connections.</li><li><strong>Outcome</strong>: block, mask, or route to an approved model. Shown only for content policies.</li><li><strong>Exceptions</strong>: when the block doesn&#39;t apply.</li><li><strong>Check &amp; save</strong>: see what it would block, then <strong>Save to draft</strong>.</li></ol><p>While you edit, the server generates and checks the Cedar. <strong>Advanced · Cedar (generated, read-only)</strong> shows the result.</p><h3 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h3><p><strong>Templates</strong> gives you ready-made starting points, for example:</p><ul><li><strong>Production connection read-only</strong></li><li><strong>Block destructive commands</strong></li><li><strong>Block secret files</strong></li><li><strong>No remote embeddings for confidential</strong></li><li><strong>Secrets never leave</strong></li><li><strong>PII masked for unapproved models</strong></li></ul><p>Pick one with <strong>Use template</strong>. The builder opens pre-filled, and you fill in only the highlighted inputs.</p><h3 id="detectors" tabindex="-1">Detectors <a class="header-anchor" href="#detectors" aria-label="Permalink to &quot;Detectors&quot;">​</a></h3><p>Detectors find sensitive content. Policies decide what happens with it. The built-in ones cover common personal and financial identifiers, email addresses, phone numbers and credentials. With <strong>+ Custom detector</strong> you add your own, for example a pattern for internal customer IDs. Custom detectors are saved into the policy draft like any other change.</p><h3 id="writing-cedar-by-hand" tabindex="-1">Writing Cedar by hand <a class="header-anchor" href="#writing-cedar-by-hand" aria-label="Permalink to &quot;Writing Cedar by hand&quot;">​</a></h3><p>Use <strong>Edit as Cedar…</strong> to turn a builder policy into hand-written Cedar. It shows as <strong>Hand-written</strong> from then on. <strong>Advanced · Edit the whole set as Cedar</strong> opens the complete custom set in one editor.</p><p>Two neutral examples:</p><div class="language-cedar vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cedar</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@id(&quot;no-rm&quot;)</span></span>
<span class="line"><span>forbid (principal, action == Action::&quot;run_command&quot;, resource)</span></span>
<span class="line"><span>when { resource.program == &quot;rm&quot; };</span></span></code></pre></div><div class="language-cedar vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cedar</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>@id(&quot;no-writes-on-legacy-crm&quot;)</span></span>
<span class="line"><span>forbid (principal, action == Action::&quot;write_connector&quot;, resource)</span></span>
<span class="line"><span>when { context.connections.contains(&quot;legacy-crm&quot;) };</span></span></code></pre></div><h3 id="test-bench" tabindex="-1">Test bench <a class="header-anchor" href="#test-bench" aria-label="Permalink to &quot;Test bench&quot;">​</a></h3><p><strong>Test bench</strong> asks the policies a question about a real Workspace and user. Nothing is executed and nothing is recorded. Save a question as a test case. Saved test cases run on every draft save and again at publish. A failing case blocks publishing.</p><h2 id="draft-review-publish" tabindex="-1">Draft, review, publish <a class="header-anchor" href="#draft-review-publish" aria-label="Permalink to &quot;Draft, review, publish&quot;">​</a></h2><p>All changes collect in one draft of the policy set:</p><ol><li><strong>Save to draft</strong> while you work. The saved test cases run each time.</li><li><strong>Submit for review</strong>. The text is now frozen (<strong>Draft in review (frozen)</strong>). You can still <strong>Withdraw</strong> it.</li><li>Another platform admin opens <strong>Review &amp; publish</strong> to see the changes, the <strong>Cedar diff</strong> and the test results, then approves.</li><li><strong>Publish</strong> makes the version live.</li></ol><p><strong>Version history</strong> lists every version with author and reviewer. <strong>Roll back</strong> creates a new draft from an older version, and that draft goes through review like any other.</p><h2 id="four-eyes-approval-rule" tabindex="-1">Four-eyes approval rule <a class="header-anchor" href="#four-eyes-approval-rule" aria-label="Permalink to &quot;Four-eyes approval rule&quot;">​</a></h2><p><strong>Admin › Rules › Approval rule</strong> sets the rule for every governed change: policies, skills, prompts, work strategies, evaluators, routing rules and the classification policy.</p><ul><li><strong>Four-eyes (a second admin approves)</strong> is the default. The person who wrote or submitted a version can&#39;t approve it.</li><li><strong>Single admin may approve own changes</strong> is meant for installations with only one admin. You approve and publish your own change in one step. Each self-approval is recorded in the audit log.</li></ul><p>Only platform admins can change the approval rule.</p><h2 id="tool-approval-policies" tabindex="-1">Tool &amp; approval policies <a class="header-anchor" href="#tool-approval-policies" aria-label="Permalink to &quot;Tool &amp; approval policies&quot;">​</a></h2><p><strong>Admin › Rules › Tool &amp; approval policies</strong> sets which tools always ask a person and which never do (because they run their own approval). There is a platform default, and each Workspace can <strong>Inherit platform default</strong> or <strong>Add to the default</strong>.</p><h2 id="command-safety" tabindex="-1">Command safety <a class="header-anchor" href="#command-safety" aria-label="Permalink to &quot;Command safety&quot;">​</a></h2><p><strong>Admin › Rules › Command safety</strong> checks every shell command an agent wants to run. It has <strong>Checks</strong> you switch on or off, an <strong>AI risk review</strong> with a <strong>Security review model</strong>, <strong>Ask a person from score</strong> and <strong>Block from score</strong>, and lists such as <strong>Always blocked</strong> and <strong>Risky shell operators</strong>. If the review model isn&#39;t available, the command waits for a person. <strong>Agent guard rules</strong> and <strong>Workspace overrides</strong> live on the same page.</p><h2 id="content-security" tabindex="-1">Content security <a class="header-anchor" href="#content-security" aria-label="Permalink to &quot;Content security&quot;">​</a></h2><p><strong>Admin › Rules › Content security</strong> shows, for each kind of data and each place it can appear, what the published policies do with it: refuse, mask or reroute, or only report. It also lists the <strong>Approved models</strong> a request can be routed to, and helps you migrate older <strong>Message filters</strong> into detectors in the policy set. The per-Workspace choice of action for each content kind is described in <a href="/docs/security/sensitive-content">Sensitive content handling</a>.</p><h2 id="limits-today" tabindex="-1">Limits today <a class="header-anchor" href="#limits-today" aria-label="Permalink to &quot;Limits today&quot;">​</a></h2><ul><li>Custom policies can only restrict (block, mask or route). They can&#39;t grant more than the baseline allows.</li><li>The engine starts in <strong>Shadow</strong>. Policies take effect as denials only in <strong>Enforce</strong>.</li></ul>`,35))])}const w=i(h,[["render",p]]);export{v as __pageData,w as default};
